<?php
declare(strict_types=1);
require_once __DIR__.'/MailSettings.php';
require_once __DIR__.'/SmtpTransport.php';
require_once __DIR__.'/LoginGeo.php';
final class AdminSecurity
{
    public function __construct(private PDO $db,private array $config,private ?Closure $sender=null,private ?LoginGeo $geo=null){}
    private function query(string $sql,array $args=[]):PDOStatement{$s=$this->db->prepare($sql);$s->execute($args);return $s;}
    private function cipher():SecretCipher{return new SecretCipher($this->config['MEDIA_DIR']??dirname(__DIR__).'/storage/media');}
    private static function uuid():string{$b=random_bytes(16);$b[6]=chr((ord($b[6])&15)|64);$b[8]=chr((ord($b[8])&63)|128);$h=bin2hex($b);return substr($h,0,8).'-'.substr($h,8,4).'-'.substr($h,12,4).'-'.substr($h,16,4).'-'.substr($h,20);}
    public static function device(mixed $in):array
    {
        if(!is_array($in)||array_diff(array_keys($in),['name','timezone','language']))throw new HttpError(400,'Thiết bị không hợp lệ.');$out=[];foreach(['name'=>100,'timezone'=>80,'language'=>40] as $k=>$max){$v=$in[$k]??'';if(!is_string($v)||!mb_check_encoding($v,'UTF-8')||strlen(mb_convert_encoding($v,'UTF-16LE','UTF-8'))/2>$max||preg_match('/[\x00-\x1f\x7f]/',$v))throw new HttpError(400,'Thiết bị không hợp lệ.');$out[$k]=$k==='name'?trim($v):$v;}return $out;
    }
    public function meta(array $device=[]):array{return ['ip'=>substr($_SERVER['REMOTE_ADDR']??'',0,80),'userAgent'=>mb_substr(preg_replace('/[\x00-\x1f\x7f]/',' ',$_SERVER['HTTP_USER_AGENT']??''),0,500),'deviceName'=>$device['name']??'','timezone'=>$device['timezone']??'','language'=>$device['language']??''];}
    public function log(string $event,string $email,?string $admin=null,array $device=[]):void{$meta=$this->meta($device);$policy=(new AdminAuth($this->db,$this->config))->policy();$meta['location']=($this->geo??new LoginGeo($this->db))->lookup($meta['ip'],!empty($policy['geoEnabled']),$event==='SUCCESS');$this->query('INSERT INTO jingo_admin_login_log(id,admin_id,email,event,data) VALUES (?,?,?,?,?)',[bin2hex(random_bytes(16)),$admin,strtolower($email),$event,json_encode($meta,JSON_THROW_ON_ERROR|JSON_INVALID_UTF8_SUBSTITUTE)]);}
    public function policy():array
    {
        $this->db->beginTransaction();try{$row=$this->query("SELECT data,version FROM jingo_admin_security WHERE id='policy' FOR UPDATE")->fetch(PDO::FETCH_ASSOC);if(!$row)throw new HttpError(503,'Chưa cài chính sách bảo mật.');$data=json_decode($row['data'],true,512,JSON_THROW_ON_ERROR);if(empty($data['entrySlug'])){$data['entrySlug']='jinmemo-'.bin2hex(random_bytes(12));$this->query("UPDATE jingo_admin_security SET data=? WHERE id='policy'",[json_encode($data,JSON_THROW_ON_ERROR)]);}$this->db->commit();return $data+['version'=>(int)$row['version']];}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}
    }
    public function challenge(array $admin,string $purpose,string $binding,array $device=[]):array
    {
        $id=self::uuid();$code=(string)random_int(100000,999999);$hash=$this->cipher()->digest('jinmemo-admin-otp-key-v1',$id.':'.$code);$meta=$this->meta($device);$expires=time()+300;
        $this->db->beginTransaction();try{$this->query("SELECT id FROM jingo_admin_security WHERE id='policy' FOR UPDATE");$this->query('SELECT id FROM jingo_admins WHERE id=? FOR UPDATE',[$admin['id']]);if($purpose==='SETUP')(new AdminAuth($this->db,$this->config))->me();$recent=$this->query('SELECT created_at FROM jingo_admin_otp WHERE admin_id=? AND purpose=? AND created_at>DATE_SUB(UTC_TIMESTAMP(),INTERVAL 15 MINUTE) ORDER BY created_at DESC',[$admin['id'],$purpose])->fetchAll(PDO::FETCH_ASSOC);if(count($recent)>=5)throw new HttpError(429,'Đã gửi quá nhiều mã. Thử lại sau 15 phút.');if($recent&&time()-strtotime($recent[0]['created_at'].' UTC')<60)throw new HttpError(429,'Chờ 60 giây trước khi gửi mã mới.');$this->query("UPDATE jingo_admin_otp SET status='USED' WHERE admin_id=? AND purpose=? AND status IN ('READY','PENDING')",[$admin['id'],$purpose]);$this->query('INSERT INTO jingo_admin_otp(id,admin_id,purpose,code_hash,binding_hash,data,expires_at) VALUES (?,?,?,?,?,?,?)',[$id,$admin['id'],$purpose,$hash,hash('sha256',$binding),json_encode($meta,JSON_THROW_ON_ERROR|JSON_INVALID_UTF8_SUBSTITUTE),gmdate('Y-m-d H:i:s',$expires)]);$this->db->commit();}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}
        try{if($this->sender)($this->sender)($admin['email'],$code,$purpose,$meta);else{$settings=new MailSettings($this->db,$this->config['MEDIA_DIR']??dirname(__DIR__).'/storage/media');$c=$settings->credentials();if(!$c)throw new RuntimeException('SMTP disabled');$text='Mã xác minh: '.$code."\n\nMã có hiệu lực 5 phút và chỉ dùng một lần. Không chia sẻ mã.\nThiết bị: ".($meta['deviceName']?:$meta['userAgent'])."\nIP ghi nhận: ".$meta['ip']."\nMúi giờ thiết bị: ".$meta['timezone'];(new SmtpTransport())->send($c,$admin['email'],$purpose==='SETUP'?'Xác minh thay đổi bảo mật':'OTP đăng nhập quản trị',$text,'ADMIN-OTP:'.$id);}$this->query("UPDATE jingo_admin_otp SET status='READY' WHERE id=? AND status='PENDING'",[$id]);$this->log('OTP_SENT',$admin['email'],$admin['id'],$device);}catch(Throwable){$this->query("UPDATE jingo_admin_otp SET status='USED' WHERE id=?",[$id]);$this->log('MAIL_FAILED',$admin['email'],$admin['id'],$device);throw new HttpError(400,'Không gửi được OTP. Kiểm tra Email & SMTP; chưa tạo phiên đăng nhập.');}
        return ['challengeId'=>$id,'expiresAt'=>gmdate('Y-m-d\TH:i:s',$expires).'.000Z','expiresIn'=>max(0,$expires-time()),'emailHint'=>preg_replace('/^(.{1,2}).*(@.*)$/','$1***$2',$admin['email']),'otpRequired'=>true];
    }
    private function consume(array $in,string $purpose,string $binding,Closure $work):mixed
    {
        if(!is_string($in['challengeId']??null)||!preg_match('/^[a-f0-9]{8}-[a-f0-9]{4}-[1-8][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/iD',$in['challengeId'])||!is_string($in['code']??null)||!preg_match('/^\d{6}$/D',$in['code']))throw new HttpError(400,'Nhập mã OTP gồm 6 chữ số.');$this->db->beginTransaction();try{$this->query("SELECT id FROM jingo_admin_security WHERE id='policy' FOR UPDATE");$row=$this->query('SELECT * FROM jingo_admin_otp WHERE id=? FOR UPDATE',[$in['challengeId']])->fetch(PDO::FETCH_ASSOC);if(!$row||$row['purpose']!==$purpose||$row['status']!=='READY'||$row['attempts']>=5||strtotime($row['expires_at'].' UTC')<=time()||!hash_equals($row['binding_hash'],hash('sha256',$binding)))throw new HttpError(401,'Mã OTP không hợp lệ hoặc đã hết hạn.');if(!hash_equals($row['code_hash'],$this->cipher()->digest('jinmemo-admin-otp-key-v1',$in['challengeId'].':'.$in['code']))){$this->query('UPDATE jingo_admin_otp SET attempts=attempts+1 WHERE id=?',[$row['id']]);$this->db->commit();throw new HttpError(401,'Mã OTP không hợp lệ hoặc đã hết hạn.');}$this->query("UPDATE jingo_admin_otp SET status='USED' WHERE id=?",[$row['id']]);$result=$work($row);$this->db->commit();return $result;}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}
    }
    public function verify(array $in,string $binding):array
    {
        if(count($in)!==2||array_diff(array_keys($in),['challengeId','code'])||!is_string($in['challengeId']??null)||!preg_match('/^[a-f0-9]{8}-[a-f0-9]{4}-[1-8][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/iD',$in['challengeId'])||!is_string($in['code']??null)||!preg_match('/^[0-9]{6}$/D',$in['code']))throw new HttpError(400,'Yêu cầu OTP không hợp lệ.');if(!preg_match('/^[a-f0-9]{64}$/D',$binding))throw new HttpError(401,'Vui lòng đăng nhập lại để nhận OTP.');return $this->consume($in,'LOGIN',$binding,function($row){$auth=new AdminAuth($this->db,$this->config);$auth->entry($auth->policy());$admin=$this->query('SELECT id,email FROM jingo_admins WHERE id=?',[$row['admin_id']])->fetch(PDO::FETCH_ASSOC);if(!$admin)throw new HttpError(401,'Không tìm thấy tài khoản.');$token=$this->session($admin['id']);$this->query('DELETE FROM jingo_admin_login_limits WHERE id=?',[hash('sha256','account:'.$admin['email'])]);$meta=json_decode($row['data'],true,512,JSON_THROW_ON_ERROR);$this->log('SUCCESS',$admin['email'],$admin['id'],['name'=>$meta['deviceName']??'','timezone'=>$meta['timezone']??'','language'=>$meta['language']??'']);return ['token'=>$token,'email'=>$admin['email']];});
    }
    private function session(string $id):string{$token=bin2hex(random_bytes(32));$this->query('DELETE FROM jingo_sessions WHERE expires_at<=UTC_TIMESTAMP()');$this->query('INSERT INTO jingo_sessions(token_hash,admin_id,expires_at) VALUES (?,?,DATE_ADD(UTC_TIMESTAMP(),INTERVAL 8 HOUR))',[hash('sha256',$token),$id]);return $token;}
    public function save(array $in,array $admin,string $binding):array
    {
        if(count($in)!==6||array_diff(array_keys($in),['version','privateEntryEnabled','otpEnabled','geoEnabled','challengeId','code'])||!is_int($in['version']??null)||$in['version']<1||$in['version']>2147483646)throw new HttpError(400,'Xác minh OTP trước khi lưu bảo mật.');foreach(['privateEntryEnabled','otpEnabled','geoEnabled'] as $k)if(!is_bool($in[$k]??null))throw new HttpError(400,'Kiểm tra lựa chọn bảo mật.');return $this->consume($in,'SETUP',$binding,function($row)use($in,$admin){if($row['admin_id']!==$admin['id'])throw new HttpError(403,'Không có quyền dùng mã này.');$auth=new AdminAuth($this->db,$this->config);$auth->me();$old=$this->query("SELECT data,version FROM jingo_admin_security WHERE id='policy'")->fetch(PDO::FETCH_ASSOC);if((int)$old['version']!==$in['version'])throw new HttpError(409,'Cấu hình đã thay đổi. Tải lại.');$policy=json_decode($old['data'],true,512,JSON_THROW_ON_ERROR);if(empty($policy['entrySlug']))throw new HttpError(409,'Tải lại cấu hình trước khi lưu.');foreach(['privateEntryEnabled','otpEnabled','geoEnabled'] as $k)$policy[$k]=$in[$k];$this->query("UPDATE jingo_admin_security SET data=?,version=version+1 WHERE id='policy'",[json_encode($policy,JSON_THROW_ON_ERROR)]);$this->query("UPDATE jingo_admin_otp SET status='USED' WHERE purpose='LOGIN' AND status IN ('READY','PENDING')");$this->query("DELETE FROM jingo_pos_sessions WHERE role='ADMIN'");$this->query('DELETE FROM jingo_sessions');$token=$this->session($admin['id']);$this->query('INSERT INTO jingo_audit(id,admin_id,action,entity_id) VALUES (?,?,?,?)',[bin2hex(random_bytes(16)),$admin['id'],'admin.security.save','policy']);$this->log('POLICY_CHANGED',$admin['email'],$admin['id']);return ['policy'=>$policy+['version'=>$in['version']+1],'token'=>$token];});
    }
    public function journal(array $in):array
    {
        if(array_diff(array_keys($in),['page'])||isset($in['page'])&&(!is_string($in['page'])||!preg_match('/^[1-9][0-9]{0,5}$/D',$in['page'])||(int)$in['page']>100000))throw new HttpError(400,'Trang nhật ký không hợp lệ.');$total=(int)$this->query('SELECT COUNT(*) FROM jingo_admin_login_log')->fetchColumn();$page=min((int)($in['page']??1),max(1,(int)ceil($total/25)));$rows=$this->query('SELECT id,email,event,data,created_at FROM jingo_admin_login_log ORDER BY created_at DESC,id DESC LIMIT 25 OFFSET '.(($page-1)*25))->fetchAll(PDO::FETCH_ASSOC);foreach($rows as &$r)$r['data']=json_decode($r['data'],true,512,JSON_THROW_ON_ERROR);return ['total'=>$total,'page'=>$page,'pageSize'=>25,'data'=>$rows];
    }
}
